begin;
create function pg_temp.master_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000002","iat":1900000000}',true);
select set_config('test.master_id',public.start_performance_review('c6100000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','2026','2026-12-31')->'review'->>'id',true);
reset role;
set constraints private.performance_review_master_enqueue immediate;
set constraints private.performance_review_master_enqueue deferred;
select pg_temp.master_assert((select desired_revision=1 from private.performance_review_master_queue),'start captures identity once');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","iat":1900000000}',true);
select public.mutate_performance_review('c6200000-0000-4000-8000-000000000001',current_setting('test.master_id')::uuid,'self:0','save_self',jsonb_build_object('answers',to_jsonb(array_fill('Synthetic private draft'::text,array[12]))));
reset role;
set constraints private.performance_review_master_enqueue immediate;
set constraints private.performance_review_master_enqueue deferred;
select pg_temp.master_assert((select desired_revision=1 and not(desired_values::text like '%Synthetic private draft%') from private.performance_review_master_queue),'employee draft never changes payload or generation');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","iat":1900000000}',true);
select set_config('test.master_answers','["=literal employee 🦽\nsecond line","","","Synthetic achievement","Synthetic challenge","Synthetic support","Safety","Quality","Grow","Care","Development",""]',true);
select public.mutate_performance_review('c6200000-0000-4000-8000-000000000002',current_setting('test.master_id')::uuid,'self:1','submit_self',jsonb_build_object('answers',current_setting('test.master_answers')::jsonb));
select set_config('test.master_employee',(public.performance_review_workspace()->'reviews'->0)::text,true);
reset role;
set constraints private.performance_review_master_enqueue immediate;
set constraints private.performance_review_master_enqueue deferred;
select pg_temp.master_assert((select desired_revision=2 and desired_values->>22=E'=literal employee 🦽\nsecond line' and desired_values->>23='' and desired_values->>24='' and desired_values->>33='' from private.performance_review_master_queue),'submitted original literal Unicode and optional blanks survive exactly');
select set_config('test.master_input','{"answers":["Manager evidence","","","Achievement","Challenge","Support","Safety","Quality","Grow","Care","Development",""],"ratings":["2 Meets expectations","N Not enough evidence","N Not enough evidence","","","","2 Meets expectations","2 Meets expectations","2 Meets expectations","2 Meets expectations","",""],"summary":"Synthetic summary","overallRating":"2 Meets expectations","managerNote":"SYNTHETIC_PRIVATE_NOTE_NEVER_MASTER"}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000002","iat":1900000000}',true);
select public.mutate_performance_review('c6300000-0000-4000-8000-000000000001',current_setting('test.master_id')::uuid,'manager:2:0','save_manager',current_setting('test.master_input')::jsonb);
select public.mutate_performance_review('c6300000-0000-4000-8000-000000000002',current_setting('test.master_id')::uuid,'manager:2:1','save_manager',current_setting('test.master_input')::jsonb||'{"managerNote":"SYNTHETIC_PRIVATE_NOTE_CHANGED"}');
reset role;
set constraints private.performance_review_master_enqueue immediate;
set constraints private.performance_review_master_enqueue deferred;
select pg_temp.master_assert((select desired_revision=2 and desired_values->>34='' and desired_values->>20='' and desired_values->>46='' from private.performance_review_master_queue),'incomplete manager and note-only changes cannot leak content or hash activity');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000002","iat":1900000000}',true);
select public.mutate_performance_review('c6300000-0000-4000-8000-000000000003',current_setting('test.master_id')::uuid,'manager:2:2','complete_manager',current_setting('test.master_input')::jsonb);
reset role;
set constraints private.performance_review_master_enqueue immediate;
set constraints private.performance_review_master_enqueue deferred;
select pg_temp.master_assert((select desired_revision=3 and desired_values->>9='Yes' and desired_values->>34='Manager evidence' and desired_values->>20='Synthetic summary' and desired_values->>47='N Not enough evidence' and jsonb_array_length(desired_values)=53 from private.performance_review_master_queue),'manager completion exposes only the exact 53 approved fields');
select set_config('test.master_meeting','{"date":"2026-01-02","time":"23:55","duration":5,"mode":"phone","location":"Synthetic phone","notes":"Synthetic draft meeting notes"}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000002","iat":1900000000}',true);
select public.mutate_performance_review('c6400000-0000-4000-8000-000000000001',current_setting('test.master_id')::uuid,'manager:2:3','save_meeting',current_setting('test.master_meeting')::jsonb);
select public.mutate_performance_review('c6400000-0000-4000-8000-000000000002',current_setting('test.master_id')::uuid,'manager:2:4','save_meeting',current_setting('test.master_meeting')::jsonb||'{"notes":"Another synthetic draft note"}');
reset role;
set constraints private.performance_review_master_enqueue immediate;
set constraints private.performance_review_master_enqueue deferred;
select pg_temp.master_assert((select desired_revision=4 and desired_values->>3='Meeting scheduled' and desired_values->>16='Phone' and desired_values->15='5'::jsonb and desired_values->>19='' and desired_values->>18='' from private.performance_review_master_queue),'recorded phone metadata never implies held or exposes draft meeting notes');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000002","iat":1900000000}',true);
select set_config('test.master_final',public.mutate_performance_review('c6400000-0000-4000-8000-000000000003',current_setting('test.master_id')::uuid,'manager:2:5','submit_review',current_setting('test.master_meeting')::jsonb||'{"held":true,"notes":"Synthetic FINAL notes"}')::text,true);
select pg_temp.master_assert(public.mutate_performance_review('c6400000-0000-4000-8000-000000000003',current_setting('test.master_id')::uuid,'manager:2:5','submit_review',current_setting('test.master_meeting')::jsonb||'{"held":true,"notes":"Synthetic FINAL notes"}')=current_setting('test.master_final')::jsonb,'final replay is byte-identical');
reset role;
set constraints private.performance_review_master_enqueue immediate;
set constraints private.performance_review_master_enqueue deferred;
select pg_temp.master_assert((select desired_revision=5 and desired_values->>3='Submitted' and desired_values->>19='Synthetic FINAL notes' and desired_values->>18='2026-01-02' from private.performance_review_master_queue),'final multi-UPDATE commit produces one generation using frozen final notes and actual held date');
select pg_temp.master_assert((select count(*)=1 and bool_and(state='queued') from private.performance_review_mail_outbox),'Master preserves original exactly-once Careers queue');
select pg_temp.master_assert(not exists(select 1 from private.performance_review_master_queue where desired_values::text like '%SYNTHETIC_PRIVATE_NOTE%') and not exists(select 1 from private.performance_review_master_attempts where approved_values::text like '%SYNTHETIC_PRIVATE_NOTE%'),'private notes never enter durable Master state');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","iat":1900000000}',true);
select pg_temp.master_assert(public.performance_review_workspace()->'reviews'->0=current_setting('test.master_employee')::jsonb,'employee DTO and revision remain identical across all manager stages');
reset role;
savepoint master_revoke;
update public.profiles set account_status='disabled' where id='a1000000-0000-4000-8000-000000000001';
update public.internal_org_people set is_active=false where id='b1000000-0000-4000-8000-000000000001';
select pg_temp.master_assert((select count(*)=1 and bool_and(desired_revision=5) from private.performance_review_master_queue),'revocation and archive are not deletion or a new projection command');
rollback to master_revoke;
savepoint master_rollback;
update private.performance_reviews set employee_identity=jsonb_set(employee_identity,'{team}','"Synthetic changed team"');
set constraints private.performance_review_master_enqueue immediate;
select pg_temp.master_assert((select desired_revision=6 from private.performance_review_master_queue),'transactional trigger actually entered before rollback');
rollback to master_rollback;
select pg_temp.master_assert((select desired_revision=5 from private.performance_review_master_queue),'rollback restores review and queue atomically');
commit;
